package com.hau.question.application.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.hau.question.application.model.*; import com.hau.question.application.port.out.*; import com.hau.question.domain.exception.ForbiddenException; import com.hau.question.domain.model.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*;
class QuestionServiceTest {QuestionRepository repo=mock(QuestionRepository.class);QuestionEventPublisher events=mock(QuestionEventPublisher.class);QuestionService service=new QuestionService(repo,events,Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC));UUID owner=UUID.randomUUID();Question q;
 @BeforeEach void init(){q=Question.create(UUID.randomUUID(),"CNTT",UUID.randomUUID(),UUID.randomUUID(),null,"Q",null,null,QuestionType.SINGLE_CHOICE,Difficulty.EASY,QuestionSource.MANUAL,null,owner,List.of(new QuestionOption(UUID.randomUUID(),"A","a",null,null,true,0),new QuestionOption(UUID.randomUUID(),"B","b",null,null,false,1)),Instant.now());when(repo.findById(q.id())).thenReturn(Optional.of(q));when(repo.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void userCannotEditAnotherUsersQuestion(){Actor other=new Actor(UUID.randomUUID(),Role.USER,"CNTT");assertThrows(ForbiddenException.class,()->service.update(q.id(),other,input()));}
 @Test void subjectAdminCannotApproveOtherFaculty(){q.submit(Instant.now());Actor admin=new Actor(UUID.randomUUID(),Role.SUBJECT_ADMIN,"KT");assertThrows(ForbiddenException.class,()->service.approve(q.id(),admin,null,UUID.randomUUID()));}
 @Test void systemAdminIsNotSpecialistReviewer(){q.submit(Instant.now());Actor admin=new Actor(UUID.randomUUID(),Role.SYSTEM_ADMIN,"CNTT");assertThrows(ForbiddenException.class,()->service.approve(q.id(),admin,null,UUID.randomUUID()));}
 private QuestionInput input(){return new QuestionInput("CNTT",q.subjectId(),q.chapterId(),null,"new",null,null,QuestionType.SINGLE_CHOICE,Difficulty.EASY,q.options());}}
